"use client";

import "./textarea.css";
import type React from "react";
import { cn } from "tailwind-variants";

import { textareaVariants, type TextareaVariants } from "./textarea.variants";

export type TextareaProps = TextareaVariants & React.TextareaHTMLAttributes<HTMLTextAreaElement>;

export const TextareaRoot = ({ className, variant, size, ...props }: TextareaProps) => {
  const slots = textareaVariants({ variant, size });

  return <textarea className={cn(slots.root(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const textareaVariants = tv({
  slots: {
    root: "textarea",
  },
  variants: {
    variant: {
      default: {
        root: "border border-input bg-background text-foreground shadow-xs placeholder:text-muted-foreground focus-visible:outline-2 focus-visible:outline-ring",
      },
      filled: {
        root: "border border-transparent bg-muted text-foreground placeholder:text-muted-foreground focus-visible:outline-2 focus-visible:outline-ring",
      },
    },
    size: {
      sm: {
        root: "min-h-16 px-2.5 py-1.5 text-xs rounded-md",
      },
      md: {
        root: "min-h-20 px-3 py-2 text-sm rounded-md",
      },
      lg: {
        root: "min-h-28 px-4 py-3 text-base rounded-lg",
      },
    },
  },
  defaultVariants: {
    variant: "default",
    size: "md",
  },
});

export type TextareaVariants = VariantProps<typeof textareaVariants>;

.textarea {
  @apply flex field-sizing-content w-full resize-y transition-colors disabled:cursor-not-allowed disabled:opacity-50;
}

import { TextareaRoot } from "./textarea";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/textarea/content.md
 */
export const Textarea = {
  Root: TextareaRoot,
};

export { TextareaRoot };

export type { TextareaProps } from "./textarea";
export { type TextareaVariants, textareaVariants } from "./textarea.variants";
